using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using MonsterRemake2D;
public class EarthSpriteImport:AssetPostprocessor {
 void OnPreprocessTexture(){if(!assetPath.StartsWith("Assets/Remake/Resources/Art/"))return;var i=(TextureImporter)assetImporter;i.textureType=TextureImporterType.Sprite;i.spriteImportMode=SpriteImportMode.Single;i.spritePivot=new Vector2(.5f,0);var settings=new TextureImporterSettings();i.ReadTextureSettings(settings);settings.spriteAlignment=(int)SpriteAlignment.Custom;settings.spritePivot=new Vector2(.5f,0);i.SetTextureSettings(settings);i.spritePixelsPerUnit=assetPath.Contains("/Characters/")?128:assetPath.Contains("/Hero/")?48:16;i.filterMode=FilterMode.Point;i.textureCompression=TextureImporterCompression.Uncompressed;i.alphaIsTransparency=true;i.mipmapEnabled=false;i.maxTextureSize=2048;if(assetPath.EndsWith("tile1_0.png"))i.isReadable=true;}
}
public static class Earth2DBuild {
 const string Scene="Assets/Remake/Scenes/Earth2D.unity";
 [MenuItem("Remake 2D/Create and verify playable earth chapter")]
 public static void Create(){Directory.CreateDirectory("Assets/Remake/Scenes");var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);new GameObject("2D earth chapter").AddComponent<EarthGame2D>();var camera=new GameObject("Top down 2D camera").AddComponent<Camera>();camera.tag="MainCamera";camera.orthographic=true;camera.transform.position=new Vector3(10,-15,-10);EditorSceneManager.SaveScene(scene,Scene);EditorBuildSettings.scenes=File.Exists("Assets/Remake/Scenes/HeroMotionPreview.unity")?new[]{new EditorBuildSettingsScene(Scene,true),new EditorBuildSettingsScene("Assets/Remake/Scenes/HeroMotionPreview.unity",true)}:new[]{new EditorBuildSettingsScene(Scene,true)};PlayerSettings.productName="Monster Wonderland 2D";PlayerSettings.companyName="Remake Study";PlayerSettings.defaultScreenWidth=1280;PlayerSettings.defaultScreenHeight=800;PlayerSettings.fullScreenMode=FullScreenMode.Windowed;PlayerSettings.runInBackground=true;PlayerSettings.colorSpace=ColorSpace.Gamma;AssetDatabase.SaveAssets();Verify();}
 public static void Verify(){
  var c=JsonUtility.FromJson<Catalog>(Resources.Load<TextAsset>("Data/catalog").text);Require(c.entries.Length==51&&c.entries.Count(e=>e.role=="monster")==50,"50 beasts and hero");Require(c.entries.All(e=>e.artPolicy=="original_reference_review"&&(e.assetStatus=="rejected_v1_placeholder"||e.assetStatus=="approved"||e.id==51&&e.assetStatus=="motion_candidate_v5")),"All art has explicit review status; this verifies loading, not visual approval");foreach(var e in c.entries)Require(Resources.Load<Sprite>(e.spriteResource)!=null,"Sprite "+e.name);var motion=Resources.Load<HeroMotionLibrary2D>("HeroMotion/Animations");Require(motion!=null&&motion.field.Length==4&&motion.battle.Length==10,"Q field and modular battle motion library");
  Require(!Directory.Exists("Assets/Remake/Resources/Models"),"No 3D model dependency");var w=JsonUtility.FromJson<World>(Resources.Load<TextAsset>("Data/earth-world").text);Require(w.maps.Length==27,"Original earth maps");foreach(var m in w.maps){Require(m.attributes.Length==m.width*m.height&&m.layer0.Length==m.attributes.Length&&m.layer1.Length==m.attributes.Length,"Map dimensions");foreach(var p in m.portals.Where(p=>!p.outside))Require(w.Find(p.toMap).arrivals.Any(a=>a.door==p.door),"Original door pair "+m.id+":"+p.key);}
  var route=JsonUtility.FromJson<ReplayRoute>(Resources.Load<TextAsset>("Data/smoke-route").text);Require(route.steps.Last().map==75,"Complete path to guardian");var back=JsonUtility.FromJson<ReplayRoute>(Resources.Load<TextAsset>("Data/smoke-return-route").text);Require(back.steps.Last().map==9,"Complete return path");
  var s=EarthSave.New(c);var chest=w.Find(64).chests.First();int before=s.Count(chest.item);Require(s.Claim(chest)&&!s.Claim(chest)&&s.Count(chest.item)==before+chest.quantity,"Chest persists one reward");var copy=JsonUtility.FromJson<EarthSave>(JsonUtility.ToJson(s));Require(copy.Valid(c,w)&&copy.opened.Count==1,"Save round trip");var hp=OriginalGrowth.Calculate(c.Find(51).rawOriginalFields,10);Require(hp.hp==285&&hp.attack==89,"Recovered Java integer growth formula");
  Require(OriginalElements.Scale(1,2,100)==125&&OriginalElements.Scale(2,1,100)==75&&OriginalElements.Scale(5,2,100)==100,"Original element bonus and resistance");
  Require(ChapterCombat.Capture(new Unit(21,5,c){hp=1},3,1)>ChapterCombat.Capture(new Unit(21,5,c),1,1),"Weaken for seal capture");Directory.CreateDirectory("../Production");File.WriteAllText("../Production/editor-validation.txt","PASS: Unity compilation, 51 loadable 2D sprites (art approval tracked separately), 36 Q field frames and modular battle motions, no FBX/model resources, 27 original terrain maps, all in-scope portal pairs, full height-aware outward/return replay, original growth integer arithmetic, one-time reward and serializable save.\nOriginal collision map45 uses a documented compatibility overlay. Runtime/UI validation is a separate report.");Debug.Log("EARTH_2D_EDITOR_PASSED");
 }
 static void Require(bool ok,string why){if(!ok)throw new Exception("2D editor verification failed: "+why);}
 public static void BuildMac(){Create();Directory.CreateDirectory("../Production/Build");var report=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{Scene},locationPathName="../Production/Build/MonsterWonderland2D.app",target=BuildTarget.StandaloneOSX,options=BuildOptions.None});Require(report.summary.result==UnityEditor.Build.Reporting.BuildResult.Succeeded,"Mac build");Debug.Log("EARTH_2D_MAC_BUILD_PASSED");}
}
